package com.greenocean.backend.professional.controller;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.auth.service.RecentAuthentication;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.http.*;import java.util.*;
@RestController @RequestMapping("/api/v1")
public class ProfessionalClinicController {
 private final ProfessionalAuthority authority;private final ProfessionalScheduling scheduling;private final CredentialDocuments documents;private final RecentAuthentication recent;private final ProfessionalReminders reminders;
 public ProfessionalClinicController(ProfessionalAuthority authority,ProfessionalScheduling scheduling,CredentialDocuments documents,RecentAuthentication recent,ProfessionalReminders reminders){this.authority=authority;this.scheduling=scheduling;this.documents=documents;this.recent=recent;this.reminders=reminders;}
 private UUID user(Jwt j){return UUID.fromString(j.getSubject());}private UUID session(Jwt j){return UUID.fromString(j.getClaimAsString("sid"));}public record Reason(@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(min=3,max=1000)String reason){} public record Materialize(boolean publish){} public record ReminderPreference(boolean enabled){} public record Revision(@jakarta.validation.constraints.Min(1)long revision){}
 @GetMapping("/professional/workspace") public Map<String,Object> workspace(@AuthenticationPrincipal Jwt j){return authority.workspace(user(j));}
 @PutMapping("/professional/workspace/profile") @ResponseStatus(HttpStatus.NO_CONTENT) public void profile(@AuthenticationPrincipal Jwt j,@jakarta.validation.Valid @RequestBody ProfessionalAuthority.Profile in){authority.profile(user(j),in);}
 @GetMapping("/admin/professional-verification-sources") public List<Map<String,Object>> sources(@AuthenticationPrincipal Jwt j){return authority.sources(user(j));}
 @GetMapping("/admin/professional-qualifications") public List<Map<String,Object>> queue(@AuthenticationPrincipal Jwt j,@RequestParam(defaultValue="0")int page){return authority.queue(user(j),page);}
 @GetMapping("/admin/professional-qualifications/{id}") public Map<String,Object> detail(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){return documents.detail(user(j),id);}
 @PostMapping("/admin/professional-qualifications/{id}/decision") @ResponseStatus(HttpStatus.NO_CONTENT) public void decide(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@jakarta.validation.Valid @RequestBody ProfessionalAuthority.Decision in){authority.decide(user(j),id,in);}
 @PostMapping("/admin/clinic-release-approvals") @ResponseStatus(HttpStatus.NO_CONTENT) public void release(@AuthenticationPrincipal Jwt j,@jakarta.validation.Valid @RequestBody ProfessionalAuthority.Release in){authority.release(user(j),in);}
 @PostMapping("/admin/professional-documents/{id}/scan") public Map<String,Object> scan(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@jakarta.validation.Valid @RequestBody Reason in){return documents.scan(user(j),id,in.reason());}
 @PostMapping("/professional-documents/{id}/content") public ResponseEntity<byte[]> document(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@jakarta.validation.Valid @RequestBody Reason in){recent.require(user(j),session(j),true);var result=documents.download(user(j),id,in.reason());return ResponseEntity.ok().cacheControl(CacheControl.noStore()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(result.filename()).build().toString()).contentType(MediaType.parseMediaType(result.mime())).body(result.bytes());}
 @PostMapping("/professional/calendar/slots") public Map<String,Object> slot(@AuthenticationPrincipal Jwt j,@jakarta.validation.Valid @RequestBody ProfessionalScheduling.Slot in){return Map.of("id",scheduling.slot(user(j),in));}
 @PostMapping("/professional/calendar/slots/{id}/publish") @ResponseStatus(HttpStatus.NO_CONTENT) public void publish(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@jakarta.validation.Valid @RequestBody Revision in){scheduling.publish(user(j),id,in.revision());}
 @PostMapping("/professional/calendar/slots/{id}/cancel") @ResponseStatus(HttpStatus.NO_CONTENT) public void cancelSlot(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@jakarta.validation.Valid @RequestBody Revision in){scheduling.cancelSlot(user(j),id,in.revision());}
 @PostMapping("/professional/calendar/rules") public Map<String,Object> rule(@AuthenticationPrincipal Jwt j,@jakarta.validation.Valid @RequestBody ProfessionalScheduling.Rule in){return Map.of("id",scheduling.rule(user(j),in));}
 @PostMapping("/professional/calendar/rules/{id}/materialize") public Map<String,Object> materialize(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@RequestBody Materialize in){return scheduling.materialize(user(j),id,in.publish());}
 @DeleteMapping("/professional/calendar/rules/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void cancel(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){scheduling.cancelRule(user(j),id);}
 @PostMapping("/professional/calendar/exceptions") public Map<String,Object> exception(@AuthenticationPrincipal Jwt j,@jakarta.validation.Valid @RequestBody ProfessionalScheduling.ExceptionWindow in){return Map.of("id",scheduling.exception(user(j),in));}
 @PostMapping("/consultations/{id}/check-in") @ResponseStatus(HttpStatus.NO_CONTENT) public void checkin(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){scheduling.checkin(user(j),session(j),id);}
 @PutMapping("/consultations/{id}/reminder-preference") @ResponseStatus(HttpStatus.NO_CONTENT) public void reminder(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@RequestBody ReminderPreference in){reminders.preference(user(j),id,in.enabled());}
 @GetMapping("/consultations/{id}/readiness") public Map<String,Object> readiness(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){return scheduling.readiness(user(j),id);}
}
